const item = $input.first();
const json = item.json || {};
const nested = json.body && typeof json.body === 'object' ? json.body : json;
const password = String(json.password ?? nested.password ?? '');
const binary = item.binary || {};
const keys = Object.keys(binary);
if (!keys.length) {
  throw new Error('缺少账单文件。请用 multipart 字段 file 上传 ZIP/CSV/XLSX。');
}
const srcKey = keys.includes('file') ? 'file' : (keys.includes('data') ? 'data' : keys[0]);
return [{
  json: { password, platform: 'wechat' },
  binary: { data: binary[srcKey] },
}];

const parsed = $input.first().json || {};
const skipped = parsed.skipped || [];
const stats = parsed.stats || { income: 0, expense: 0, count: 0, skipped: skipped.length };
const transactions = parsed.transactions || [];
const batchId = String($execution.id || '');

const appId = $env.FEISHU_APP_ID;
const appSecret = $env.FEISHU_APP_SECRET;
const appToken = $env.FEISHU_WECHAT_BILL_BASE_ID || $env.FEISHU_BASE_ID;
const tableId = $env.FEISHU_WECHAT_BILL_TABLE_ID;

if (!appId || !appSecret || !appToken || !tableId) {
  throw new Error('缺少飞书环境变量：FEISHU_APP_ID / FEISHU_APP_SECRET / FEISHU_WECHAT_BILL_BASE_ID / FEISHU_WECHAT_BILL_TABLE_ID');
}

const summary = {
  ok: true,
  imported: 0,
  duplicates: 0,
  skipped: skipped.length,
  stats,
  created_record_ids: [],
  duplicate_tx_ids: [],
};

if (!transactions.length) {
  return [{ json: summary }];
}

const helpers = this.helpers;

function toMs(value) {
  const text = String(value || '').trim();
  if (!text) return null;
  const d = new Date(text.replace(' ', 'T') + '+08:00');
  const ms = d.getTime();
  return Number.isNaN(ms) ? null : ms;
}

function fieldsOf(tx) {
  const fields = {
    '交易类型': tx.tx_type || '',
    '交易对方': tx.peer || '',
    '商品': tx.item || '',
    '收支': tx.direction || '',
    '金额': tx.amount,
    '支付方式': tx.method || '',
    '当前状态': tx.status || '',
    '交易单号': tx.tx_id || '',
    '商户单号': tx.merchant_order_id || '',
    '备注': tx.note || '',
    '分类': tx.category || '未分类',
    '来源': '微信',
    '导入批次': batchId,
  };
  const ms = toMs(tx.time);
  if (ms != null) fields['交易时间'] = ms;
  return fields;
}

async function feishu(method, url, body) {
  const resp = await helpers.httpRequest({
    method,
    url,
    headers: {
      Authorization: 'Bearer ' + token,
      'Content-Type': 'application/json; charset=utf-8',
    },
    body,
    json: true,
  });
  if (resp && typeof resp.code === 'number' && resp.code !== 0) {
    throw new Error('飞书 API 失败 ' + resp.code + ': ' + (resp.msg || JSON.stringify(resp)));
  }
  return resp;
}

const tokenResp = await helpers.httpRequest({
  method: 'POST',
  url: 'https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal',
  headers: { 'Content-Type': 'application/json; charset=utf-8' },
  body: { app_id: appId, app_secret: appSecret },
  json: true,
});
if (!tokenResp || !tokenResp.tenant_access_token) {
  throw new Error('获取飞书 tenant_access_token 失败: ' + JSON.stringify(tokenResp));
}
const token = tokenResp.tenant_access_token;
const searchUrl = 'https://open.feishu.cn/open-apis/bitable/v1/apps/' + appToken + '/tables/' + tableId + '/records/search';
const createUrl = 'https://open.feishu.cn/open-apis/bitable/v1/apps/' + appToken + '/tables/' + tableId + '/records/batch_create';

const existing = new Set();
const txIds = transactions.map((t) => String(t.tx_id || '')).filter(Boolean);

for (let i = 0; i < txIds.length; i += 50) {
  const chunk = txIds.slice(i, i + 50);
  let pageToken = '';
  do {
    const body = {
      field_names: ['交易单号'],
      filter: {
        conjunction: 'or',
        conditions: chunk.map((id) => ({
          field_name: '交易单号',
          operator: 'is',
          value: [id],
        })),
      },
      page_size: 500,
    };
    if (pageToken) body.page_token = pageToken;
    const found = await feishu('POST', searchUrl, body);
    const items = (found.data && found.data.items) || [];
    for (const rec of items) {
      const value = rec.fields && rec.fields['交易单号'];
      const id = Array.isArray(value) ? String(value[0] || '') : String(value || '');
      if (id) existing.add(id);
    }
    pageToken = (found.data && found.data.page_token) || '';
  } while (pageToken);
}

const fresh = [];
for (const tx of transactions) {
  const id = String(tx.tx_id || '');
  if (id && existing.has(id)) {
    summary.duplicates += 1;
    summary.duplicate_tx_ids.push(id);
    continue;
  }
  fresh.push(tx);
}

for (let i = 0; i < fresh.length; i += 500) {
  const chunk = fresh.slice(i, i + 500);
  const created = await feishu('POST', createUrl, {
    records: chunk.map((tx) => ({ fields: fieldsOf(tx) })),
  });
  const records = (created.data && created.data.records) || [];
  for (const rec of records) {
    if (rec.record_id) summary.created_record_ids.push(rec.record_id);
  }
  summary.imported += records.length || chunk.length;
}

return [{ json: summary }];
